        "--version" | "-V" | "version" => println!("pyfun {}", VERSION),
        "check" => cmd_check(rest),
        "compile" => cmd_compile(rest),
        "run" => cmd_run(rest),
        "parse" => cmd_parse(rest),
        "bundle" => bundle::cmd_bundle(rest),
        "build" => bundle::cmd_build(rest),
        "add" => pkg::cmd_add(rest),
        "install" => pkg::cmd_install(rest),
        "remove" => pkg::cmd_remove(rest),
        "repl" => repl::run_repl(),
        "kernel-engine" => kernel::run_kernel(),
        "lsp" => lsp::run_lsp(),
        _ => cmd_compile(&args[..1]),
    }
}
// rustc-style diagnostics.

use crate::source::{line_col, line_text, Span};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Severity {
    Error,
    Note,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Diag {
    pub severity: Severity,
    pub msg: String,
    pub span: Span,
}

impl Diag {
    pub fn error(msg: impl Into<String>, span: Span) -> Diag {
        Diag { severity: Severity::Error, msg: msg.into(), span }
    }
    pub fn note(msg: impl Into<String>, span: Span) -> Diag {
        Diag { severity: Severity::Note, msg: msg.into(), span }
    }
}

/// Render one diagnostic against its source, without a trailing newline.
pub fn render(src: &str, d: &Diag) -> String {
    let head = match d.severity {
        Severity::Error => "error",
        Severity::Note => "note",
    };
    let (line, col) = line_col(src, d.span.lo);
    let text = line_text(src, line);
    let lnum = line.to_string();
    let pad = " ".repeat(lnum.len());
    // the caret covers the span's bytes on its first line, at least one
    let line_end = col - 1 + (text.len() + 1 - col.min(text.len() + 1));
    let hi_col = {
        let (hl, hc) = line_col(src, d.span.hi);
        if hl == line {
            hc - 1
        } else {
            line_end
        }
    };
    let n = if hi_col > col - 1 { hi_col - (col - 1) } else { 1 };
    format!(
        "{}: {}\n{}--> {}:{}\n{} |\n{} | {}\n{} | {}{}",
        head,
        d.msg,
        pad,
        line,
        col,
        pad,
        lnum,
        text,
        pad,
        " ".repeat(col - 1),
        "^".repeat(n)
    )
}
// Lexer: bytes -> tokens with positions. Layout is decided by the parser from
// each token's column and whether it starts a line.

use crate::diag::Diag;
use crate::source::Span;

#[derive(Clone, Debug, PartialEq)]
pub enum Tok {
    Int(i64),
    Float(f64),
    Str(String),
    FStr(Vec<FPiece>),
    Ident(String),
    Upper(String),
    Hole(Option<String>),
    // keywords
    Let,
    Mut,
    Pure,
    Type,
    Measure,
    Extern,
    Import,
    Module,
    If,
    Then,
    Elif,
    Else,
    Match,
    Case,
    Fun,
    And,
    Or,
    Not,
    True,
    False,
    Return,
    With,
    As,
    Yield,
    Do,
    Try,
    // punctuation
    LParen,
    RParen,
    LBracket,
    RBracket,
    LBrace,
    RBrace,
    Comma,
    Dot,
    Ellipsis,
    Colon,
    Eq,
    Arrow,
    LArrow,
    Bar,
    Underscore,
    Bang,
    Caret,
    // operators
    Plus,
    Minus,
    Star,
    Slash,
    SlashSlash,
    Percent,
    StarStar,
    EqEq,
    NotEq,
    Lt,
    Le,
    Gt,
    Ge,
    PipeRight,
    PipeLeft,
    ComposeRight,
    ComposeLeft,
    /// (recovering) where a token failed to lex: it takes its place in the
    /// layout, and an expression simply skips it
    LexError,
    Eof,
}

#[derive(Clone, Debug, PartialEq)]
pub enum FPiece {
    Text(String),
    /// A `{...}` hole: its tokens (ending in Eof), the span of the content, and
    /// for `{expr=}` the source text echoed before the value.
    Hole { toks: Vec<Token>, span: Span, debug: Option<String> },
}

#[derive(Clone, Debug, PartialEq)]
pub struct Token {
    pub tok: Tok,
    pub span: Span,
    pub line: usize,
    pub col: usize,
    /// first token on its line
    pub bol: bool,
    /// whitespace (or a comment) right before this token
    pub space_before: bool,
}

pub fn describe(t: &Tok) -> String {
    match t {
        Tok::Int(n) => format!("integer `{}`", n),
        Tok::Float(f) => format!("float `{}`", f),
        Tok::Str(_) => "string literal".to_string(),
        Tok::Ident(s) | Tok::Upper(s) => format!("identifier `{}`", s),
        Tok::Eof => "end of input".to_string(),
        other => format!("`{}`", tok_text(other)),
    }
}

pub fn tok_text(t: &Tok) -> &'static str {
    match t {
        Tok::Let => "let",
        Tok::Mut => "mut",
        Tok::Pure => "pure",
        Tok::Type => "type",
