142	                    eprintln!("cannot restart python worker: {}", e);
143	                    w.kill();
144	                    return;
145	                }
146	            }
147	        } else {
148	            self.session.sent.clear();
149	        }
150	        match w.request(code) {
151	            Ok(o) => {
152	                print!("{}", o);
153	                let _ = out.lock().flush();
154	                self.worker = Some(w);
155	            }
156	            Err(e) => {
157	                eprintln!("python worker failed again: {}", e);
158	                w.kill();
159	            }
160	        }
161	    }
162	
163	    fn eval(&mut self, input: &str, block: bool) {
164	        match self.session.eval(input, block) {
165	            Ok(r) => {
166	                for e in &r.echoes {
167	                    println!("{}", e);
168	                }
169	                if !r.code.is_empty() {
170	                    self.run(&r.code);
171	                }
172	            }
173	            Err(EvalErr::Parse(s)) => eprintln!("{}", s),
174	            Err(EvalErr::Type(errs)) => {
175	                for e in errs {
176	                    eprintln!("{}", e);
177	                }
178	            }
179	            Err(EvalErr::Compile(echoes, errs)) => {
180	                for e in &echoes {
181	                    println!("{}", e);
182	                }
183	                for e in errs {
184	                    eprintln!("{}", e);
185	                }
186	            }
187	        }
188	    }
189	}
