229	/// A single program's module name: its lowercased stem, or a `_pf_` name
230	/// when that is not a plain identifier.
231	fn single_module_name(file: &str) -> String {
232	    let stem = Path::new(file).file_stem().map(|s| s.to_string_lossy().to_lowercase()).unwrap_or_default();
233	    let plain = !stem.is_empty() && stem.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_') && !stem.starts_with(|c: char| c.is_ascii_digit());
234	    if plain {
235	        stem
236	    } else {
237	        let s: String = stem.chars().map(|c| if c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_' { c } else { '_' }).collect();
238	        format!("_pf_{}", s)
239	    }
240	}
