242	pub fn cmd_build(args: &[String]) {
243	    let mut native = false;
244	    let mut file: Option<String> = None;
245	    let mut out: Option<String> = None;
246	    let mut i = 0;
247	    while i < args.len() {
248	        match args[i].as_str() {
249	            "--native" => native = true,
250	            "-o" => {
251	                if let Some(v) = args.get(i + 1) {
252	                    out = Some(v.clone());
253	                    i += 1;
254	                }
255	            }
256	            a => {
257	                if file.is_some() {
258	                    crate::fail(&format!("error: unexpected argument `{}`", a));
259	                }
260	                file = Some(a.to_string());
261	            }
262	        }
263	        i += 1;
264	    }
265	    if !native {
266	        crate::fail("error: `build` compiles with mypyc and needs `--native` (pyfun build --native <file> -o <dir>)");
267	    }
268	    let Some(file) = file else { crate::fail("error: `build` needs a file path") };
269	    let Some(out) = out else { crate::fail("error: `build` needs an output directory (-o <dir>)") };
270	    let ck = crate::load_checked(&file, true);
271	    let em = crate::project::emit_all(&ck, &crate::project::EmitOpts { py311: false, native: true });
272	    let project = ck.mods.len() > 1;
273	    let (files, modules, entry): (Vec<(String, String)>, Vec<String>, String) = if project {
274	        let modules: Vec<String> = em.files.iter().map(|(f, _)| f.clone()).filter(|f| f != "_pyfun_rt.py").collect();
275	        let entry = crate::project::py_module_of(&ck.mods.last().unwrap().file);
276	        (em.files.clone(), modules, entry)
277	    } else {
278	        let name = single_module_name(&file);
279	        let f = format!("{}.py", name);
280	        (vec![(f.clone(), em.files[0].1.clone())], vec![f], name)
281	    };
282	    let dir = Path::new(&out);
283	    if let Err(e) = std::fs::create_dir_all(dir) {
284	        crate::fail(&format!("error: cannot create {}: {}", out, e));
285	    }
286	    for (f, text) in &files {
287	        let p = dir.join(f);
288	        if let Err(e) = std::fs::write(&p, text) {
289	            crate::fail(&format!("error: cannot write {}: {}", p.display(), e));
290	        }
291	    }
292	    let python = crate::pkg::package_python();
293	    let status = std::process::Command::new(&python).arg("-m").arg("mypyc").args(MYPYC_FLAGS).args(&modules).current_dir(dir).status();
294	    match status {
295	        Ok(s) if s.success() => {}
296	        Ok(_) => crate::fail("error: mypyc could not build the program (see its output above); it needs `pip install mypy setuptools` and a C compiler"),
297	        Err(e) => crate::fail(&format!("error: cannot run {}: {}", python, e)),
298	    }
299	    // the extension modules replace the Python sources
300	    for m in &modules {
301	        let _ = std::fs::remove_file(dir.join(m));
302	    }
303	    let main = format!("# Runs the mypyc-compiled Pyfun program `{}`.\nimport {}  # noqa: F401\n", entry, entry);
304	    if let Err(e) = std::fs::write(dir.join("__main__.py"), main) {
305	        crate::fail(&format!("error: cannot write {}: {}", dir.join("__main__.py").display(), e));
306	    }
307	    println!("built {} natively: run it with `python {}`", file, out);
308	}
