  9	const METADATA_SCRIPT: &str = "import importlib.metadata as m, sys
 10	d = m.distribution(sys.argv[1])
 11	print(d.version)
 12	for f in d.files or []:
 13	    if str(f).endswith('.pyfun'):
 14	        print(d.locate_file(f))
