 28	/// The façade directories a program at `main` sees: those vendored next to
 29	/// the pyfun.toml found from the program's directory upward.
 30	pub fn facade_dirs(main: &Path) -> Vec<PathBuf> {
 31	    let parent = main.parent().unwrap_or(Path::new(""));
 32	    for dir in parent.ancestors() {
 33	        if dir.join("pyfun.toml").is_file() {
 34	            let mut dirs: Vec<PathBuf> = match std::fs::read_dir(dir.join(".pyfun").join("facades")) {
 35	                Ok(rd) => rd.filter_map(|e| e.ok()).map(|e| e.path()).filter(|p| p.is_dir()).collect(),
 36	                Err(_) => Vec::new(),
 37	            };
 38	            dirs.sort();
 39	            return dirs;
 40	        }
 41	    }
 42	    Vec::new()
 43	}
