 78	// ---- pyfun.toml, edited line by line ------------------------------------
 79	
 80	struct Toml {
 81	    path: PathBuf,
 82	    lines: Vec<String>,
 83	}
 84	
 85	fn section_of(line: &str) -> Option<String> {
 86	    let t = line.trim();
 87	    if t.starts_with('[') && t.ends_with(']') && t.len() >= 2 {
 88	        Some(t[1..t.len() - 1].trim().to_string())
 89	    } else {
 90	        None
 91	    }
 92	}
 93	
 94	/// `key = "value"` (a trailing comment allowed): the key and value.
 95	fn dep_entry(line: &str) -> Option<(String, String)> {
 96	    if line.trim_start().starts_with('#') {
 97	        return None;
 98	    }
 99	    let (k, v) = line.split_once('=')?;
100	    let k = k.trim();
101	    let k = if k.len() >= 2 && k.starts_with('"') && k.ends_with('"') { &k[1..k.len() - 1] } else { k };
102	    let v = v.trim().strip_prefix('"')?;
103	    let close = v.find('"')?;
104	    let rest = v[close + 1..].trim();
105	    if !rest.is_empty() && !rest.starts_with('#') {
106	        return None;
107	    }
108	    Some((k.to_string(), v[..close].to_string()))
109	}
110	
111	impl Toml {
112	    fn load(path: &Path) -> Toml {
113	        let text = match std::fs::read_to_string(path) {
114	            Ok(t) => t,
115	            Err(e) => fail(&format!("cannot read {}: {}", path.display(), e)),
116	        };
117	        Toml { path: path.to_path_buf(), lines: text.lines().map(|l| l.to_string()).collect() }
118	    }
119	
120	    /// Each dependency entry: (line index, name, version).
121	    fn deps(&self) -> Vec<(usize, String, String)> {
122	        let mut out = Vec::new();
123	        let mut in_deps = false;
124	        for (i, l) in self.lines.iter().enumerate() {
125	            if let Some(s) = section_of(l) {
126	                in_deps = s == "dependencies";
127	                continue;
128	            }
129	            if in_deps {
130	                if let Some((k, v)) = dep_entry(l) {
131	                    out.push((i, k, v));
132	                }
133	            }
134	        }
135	        out
136	    }
137	
138	    fn set(&mut self, name: &str, version: &str) {
139	        let entry = format!("{} = \"{}\"", name, version);
140	        if let Some((i, _, _)) = self.deps().into_iter().find(|(_, k, _)| k == name) {
141	            self.lines[i] = entry;
142	            return;
143	        }
144	        // after the last entry of the dependencies section (or its header)
145	        let mut at: Option<usize> = None;
146	        let mut in_deps = false;
147	        for (i, l) in self.lines.iter().enumerate() {
148	            if let Some(s) = section_of(l) {
149	                in_deps = s == "dependencies";
150	                if in_deps {
151	                    at = Some(i);
152	                }
153	                continue;
154	            }
155	            let t = l.trim();
156	            if in_deps && !t.is_empty() && !t.starts_with('#') {
157	                at = Some(i);
158	            }
159	        }
160	        match at {
161	            Some(i) => self.lines.insert(i + 1, entry),
162	            None => {
163	                if self.lines.last().map_or(false, |l| !l.trim().is_empty()) {
164	                    self.lines.push(String::new());
165	                }
166	                self.lines.push("[dependencies]".to_string());
167	                self.lines.push(entry);
168	            }
169	        }
170	    }
171	
172	    fn remove(&mut self, name: &str) -> bool {
173	        match self.deps().into_iter().find(|(_, k, _)| k == name) {
174	            Some((i, _, _)) => {
175	                self.lines.remove(i);
176	                true
177	            }
178	            None => false,
179	        }
180	    }
181	
182	    fn save(&self) {
183	        let mut text = self.lines.join("\n");
184	        text.push('\n');
185	        if let Err(e) = std::fs::write(&self.path, text) {
186	            fail(&format!("cannot write {}: {}", self.path.display(), e));
187	        }
188	    }
189	}
