191	// ---- installing ----------------------------------------------------------
192	
193	/// Install `spec`, vendor its .pyfun files and record it.
194	fn add_one(spec: &str, toml: &mut Toml) {
195	    let name = package_name(spec);
196	    let python = package_python();
197	    let status = if have_uv() {
198	        Command::new("uv").args(["pip", "install", "--python", &python, spec]).status()
199	    } else {
200	        Command::new(&python).args(["-m", "pip", "install", spec]).status()
201	    };
202	    match status {
203	        Ok(s) if s.success() => {}
204	        Ok(_) => fail(&format!("installing `{}` failed (see the installer's output above)", spec)),
205	        Err(e) => fail(&format!("cannot run the installer: {}", e)),
206	    }
207	    let out = match Command::new(&python).arg("-c").arg(METADATA_SCRIPT).arg(&name).stdin(Stdio::null()).output() {
208	        Ok(o) => o,
209	        Err(e) => fail(&format!("cannot run {}: {}", python, e)),
210	    };
211	    if !out.status.success() {
212	        let err = String::from_utf8_lossy(&out.stderr);
213	        fail(&format!("cannot read the installed metadata of `{}`: {}", name, err.trim_end()));
214	    }
215	    let text = String::from_utf8_lossy(&out.stdout).to_string();
216	    let mut lines = text.lines();
217	    let version = lines.next().unwrap_or("").trim().to_string();
218	    let files: Vec<&str> = lines.collect();
219	    if files.is_empty() {
220	        fail(&format!("`{}` installed, but it ships no .pyfun files, so it is not a Pyfun façade", name));
221	    }
222	    let root = toml.path.parent().map(|p| p.to_path_buf()).unwrap_or_default();
223	    let dir = root.join(".pyfun").join("facades").join(normalized(&name));
224	    if dir.exists() {
225	        let _ = std::fs::remove_dir_all(&dir);
226	    }
227	    if let Err(e) = std::fs::create_dir_all(&dir) {
228	        fail(&format!("cannot create {}: {}", dir.display(), e));
229	    }
230	    let mut modules = Vec::new();
231	    for f in files {
232	        let src = Path::new(f);
233	        let Some(fname) = src.file_name() else { fail(&format!("odd façade path {}", f)) };
234	        if let Err(e) = std::fs::copy(src, dir.join(fname)) {
235	            fail(&format!("cannot copy {}: {}", f, e));
236	        }
237	        modules.push(crate::project::module_name_of(src));
238	    }
239	    modules.sort();
240	    toml.set(&name, &version);
241	    toml.save();
242	    println!("added {} {} (import {})", name, version, modules.join(", "));
243	}
