268	pub fn cmd_install(_args: &[String]) {
269	    let Some(path) = find_toml() else { fail("no pyfun.toml here or in any parent directory (`pyfun add <package>` creates one)") };
270	    let mut toml = Toml::load(&path);
271	    let deps = toml.deps();
272	    if deps.is_empty() {
273	        println!("no dependencies in pyfun.toml");
274	        return;
275	    }
276	    for (_, name, version) in deps {
277	        let spec = if version.is_empty() { name.clone() } else { format!("{}=={}", name, version) };
278	        add_one(&spec, &mut toml);
279	    }
280	}
