282	pub fn cmd_remove(args: &[String]) {
283	    if args.is_empty() {
284	        fail("`remove` needs a package name");
285	    }
286	    let Some(path) = find_toml() else { fail("no pyfun.toml here or in any parent directory (`pyfun add <package>` creates one)") };
287	    let mut toml = Toml::load(&path);
288	    let root = path.parent().map(|p| p.to_path_buf()).unwrap_or_default();
289	    for name in args {
290	        if !toml.remove(name) {
291	            fail(&format!("`{}` is not a dependency in pyfun.toml", name));
292	        }
293	        let python = package_python();
294	        let _ = if have_uv() {
295	            Command::new("uv").args(["pip", "uninstall", "--python", &python, name]).status()
296	        } else {
297	            Command::new(&python).args(["-m", "pip", "uninstall", "-y", name]).status()
298	        };
299	        let dir = root.join(".pyfun").join("facades").join(normalized(name));
300	        let _ = std::fs::remove_dir_all(&dir);
301	        println!("removed {}", name);
302	    }
303	    toml.save();
304	}

     1	//! Interactive REPL: `pyfun repl` (or bare `pyfun` with no file arg later).
     2	//!
     3	//! Pyfun is compiled, so there is no interpreter to step — instead the REPL pairs
     4	//! the Rust checker with one **long-lived Python worker process** holding a single
     5	//! namespace for the whole session. Each entry is type-checked (via `analyze`)
     6	//! against the session's accumulated definition source, and what reaches Python is
     7	//! the *diff*: the emitter is deterministic, so the emitted program is split into
     8	//! top-level statement chunks and only chunks not yet `exec`'d in the worker are
     9	//! sent (length-framed over the worker's stdin/stdout) and run in the persistent
    10	//! namespace.
    11	//!
    12	//! Consequences (python/ghci/fsi-like semantics): a definition's effects run
    13	//! exactly **once, at entry**; an expression runs once per entry (re-entering it
    14	//! re-runs it); state — including top-level `let mut` — persists across entries.
    15	//! A definition echoes its inferred type (GHCi-style); an ill-typed entry is
    16	//! rejected and changes nothing. Re-entering a definition with a different body
    17	//! emits different chunks, which rebind the names in the worker. If the worker
    18	//! dies it is respawned and the namespace rebuilt by re-running the accumulated
    19	//! definitions (their effects re-run; the REPL warns). Entries are single-line
    20	//! unless wrapped in `:{ … :}`. Known limitation: entered code that *reads* stdin
    21	//! would consume the framing protocol's bytes.
    22	
    23	use std::collections::HashSet;
    24	use std::io::{self, Read, Write};
    25	use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};
    26	
    27	use pyfun::diagnostics::{self, Level};
    28	use pyfun::syntax::Item;
    29	
    30	/// The driver program fed to `python -c`: a tiny framed-message loop that
    31	/// `exec`s each received blob in one persistent dict namespace, capturing
    32	/// stdout/stderr during the exec (any exception's traceback included) and sending
    33	/// the captured text back. Framing, both directions: 8 ASCII digits (the payload
    34	/// byte length) followed by that many UTF-8 bytes. EOF on stdin ends the loop.
    35	const DRIVER: &str = r#"
    36	import io, sys, traceback
    37	ns = {}
    38	inp = sys.stdin.buffer
    39	out = sys.stdout.buffer
    40	while True:
    41	    header = inp.read(8)
    42	    if len(header) < 8:
    43	        break
    44	    code = inp.read(int(header)).decode('utf-8')
    45	    buf = io.StringIO()
    46	    saved = sys.stdout, sys.stderr
    47	    sys.stdout = sys.stderr = buf
    48	    try:
    49	        exec(code, ns)
    50	    except BaseException:
    51	        traceback.print_exc()
    52	    finally:
    53	        sys.stdout, sys.stderr = saved
    54	    payload = buf.getvalue().encode('utf-8')
    55	    out.write(b'%08d' % len(payload))
    56	    out.write(payload)
    57	    out.flush()
    58	"#;
    59	
    60	/// Run the REPL loop. Returns success unless the environment is unusable (no
    61	/// Python interpreter, or stdin closes — which is a normal exit).
    62	pub fn run() -> std::process::ExitCode {
    63	    let Some(interp) = python_cmd() else {
    64	        eprintln!("no Python interpreter found on PATH (tried `python`, `python3`)");
    65	        return std::process::ExitCode::FAILURE;
    66	    };
