   245	pub fn cmd_add(args: &[String]) {
   246	    if args.is_empty() {
   247	        fail("`add` needs a package, e.g. `pyfun add pyfun-textwrap`");
   248	    }
   249	    let path = match find_toml() {
   250	        Some(p) => p,
   251	        None => {
   252	            let cwd = std::env::current_dir().unwrap_or_default();
   253	            let name = cwd.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
   254	            let p = cwd.join("pyfun.toml");
   255	            if let Err(e) = std::fs::write(&p, format!("[project]\nname = \"{}\"\n\n[dependencies]\n", name)) {
   256	                fail(&format!("cannot write {}: {}", p.display(), e));
   257	            }
   258	            println!("created pyfun.toml");
   259	            p
   260	        }
   261	    };
   262	    let mut toml = Toml::load(&path);
   263	    for spec in args {
   264	        add_one(spec, &mut toml);
   265	    }
   266	}
   267	
   268	pub fn cmd_install(_args: &[String]) {
   269	    let Some(path) = find_toml() else { fail("no pyfun.toml here or in any parent directory (`pyfun add <package>` creates one)") };
   270	    let mut toml = Toml::load(&path);
   271	    let deps = toml.deps();
   272	    if deps.is_empty() {
   273	        println!("no dependencies in pyfun.toml");
   274	        return;
   275	    }
   276	    for (_, name, version) in deps {
   277	        let spec = if version.is_empty() { name.clone() } else { format!("{}=={}", name, version) };
   278	        add_one(&spec, &mut toml);
   279	    }
   280	}
   281	
   282	pub fn cmd_remove(args: &[String]) {
   283	    if args.is_empty() {
   284	        fail("`remove` needs a package name");
   285	    }
   286	    let Some(path) = find_toml() else { fail("no pyfun.toml here or in any parent directory (`pyfun add <package>` creates one)") };
   287	    let mut toml = Toml::load(&path);
   288	    let root = path.parent().map(|p| p.to_path_buf()).unwrap_or_default();
   289	    for name in args {
   290	        if !toml.remove(name) {
   291	            fail(&format!("`{}` is not a dependency in pyfun.toml", name));
   292	        }
   293	        let python = package_python();
   294	        let _ = if have_uv() {
   295	            Command::new("uv").args(["pip", "uninstall", "--python", &python, name]).status()
   296	        } else {
   297	            Command::new(&python).args(["-m", "pip", "uninstall", "-y", name]).status()
   298	        };
   299	        let dir = root.join(".pyfun").join("facades").join(normalized(name));
   300	        let _ = std::fs::remove_dir_all(&dir);
   301	        println!("removed {}", name);
   302	    }
   303	    toml.save();
   304	}
