115	pub fn analyze(uri: &str, text: &str) -> Analysis {
116	    let (prog, lex_errors, parse_errors) = crate::parser::parse_program_recover(text);
117	    let mut syntax: Vec<Diag> = lex_errors;
118	    syntax.extend(parse_errors);
119	    syntax.sort_by_key(|d| d.span.lo);
120	    let imports: Vec<String> = prog.decls.iter().filter_map(|d| if let Decl::Import(n, _) = d { Some(n.clone()) } else { None }).collect();
121	    let mut module_files = Vec::new();
122	    let mut checker = Some(Checker::new());
123	    if !imports.is_empty() {
124	        // the modules this document imports come from disk, next to it
125	        let path = uri_to_path(uri).unwrap_or_else(|| PathBuf::from("main.pyfun"));
126	        match crate::project::load(&path, text.to_string()) {
127	            Ok(mods) => {
128	                let mut exports: std::collections::HashMap<String, crate::project::Exports> = Default::default();
129	                for m in &mods[..mods.len() - 1] {
130	                    let mut c = Checker::new();
131	                    for imp in &m.imports {
132	                        if let Some(ex) = exports.get(imp) {
133	                            crate::project::install_exports(&mut c, imp, ex);
134	                        }
135	                    }
136	                    c.check_program(&m.prog);
137	                    exports.insert(m.name.clone(), crate::project::collect_exports(&c, &m.prog));
138	                    module_files.push((m.name.clone(), m.path.clone(), Some(c), m.prog.clone()));
139	                }
140	                let c = checker.as_mut().unwrap();
141	                for imp in &imports {
142	                    if let Some(ex) = exports.get(imp) {
143	                        crate::project::install_exports(c, imp, ex);
144	                    }
145	                }
146	            }
147	            // modules that cannot be loaded are simply missing
148	            Err(_) => {}
149	        }
150	    }
151	    if let Some(c) = checker.as_mut() {
152	        c.source = text.to_string();
153	        c.check_program(&prog);
154	    }
155	    let res = crate::resolve::resolve(&prog);
156	    Analysis { src: text.to_string(), prog, syntax, checker, module_files, res }
157	}
