941	fn read_headers(r: &mut impl BufRead) -> Option<usize> {
942	    let mut len: Option<usize> = None;
943	    let mut bad = false;
944	    loop {
945	        let mut line = Vec::new();
946	        match r.read_until(b'\n', &mut line) {
947	            Ok(0) | Err(_) => return None,
948	            Ok(_) => {}
949	        }
950	        let text = String::from_utf8_lossy(&line);
951	        let t = text.trim();
952	        if t.is_empty() {
953	            break;
954	        }
955	        if let Some(v) = t.strip_prefix("Content-Length:") {
956	            match v.trim().parse::<usize>() {
957	                Ok(n) => len = Some(n),
958	                Err(_) => bad = true,
959	            }
960	        }
961	    }
962	    if bad {
963	        return None;
964	    }
965	    len
