  1753	/// Read one `Content-Length`-framed message body, or `None` at EOF.
  1754	fn read_message<R: BufRead>(reader: &mut R) -> io::Result<Option<String>> {
  1755	    let mut content_length: Option<usize> = None;
  1756	    loop {
  1757	        let mut line = String::new();
  1758	        if reader.read_line(&mut line)? == 0 {
  1759	            return Ok(None); // EOF
  1760	        }
  1761	        let trimmed = line.trim_end_matches(['\r', '\n']);
  1762	        if trimmed.is_empty() {
  1763	            break; // blank line ends the header block
  1764	        }
  1765	        if let Some(rest) = trimmed.strip_prefix("Content-Length:") {
  1766	            content_length = rest.trim().parse().ok();
  1767	        }
  1768	    }
  1769	    let Some(len) = content_length else {
  1770	        return Ok(None);
  1771	    };
  1772	    let mut buf = vec![0u8; len];
  1773	    reader.read_exact(&mut buf)?;
  1774	    Ok(Some(String::from_utf8_lossy(&buf).into_owned()))
  1775	}
